fn lookup(table: &'static [(&'static str, &'static str)], key: &str) -> Option<&'static str> {
    table
        .binary_search_by(|probe| probe.0.cmp(key))
        .ok()
        .map(|i| table[i].1)
}

/// Raw localized string for `key` (`"de"` or anything else for English).
/// Returns `None` when the key is missing (caller falls back to the key).
pub fn get_raw(lang: &str, key: &str) -> Option<&'static str> {
    let table = if lang.starts_with("de") {
        STRINGS_DE
    } else {
        STRINGS_EN
    };
    lookup(table, key)
}

/// Number of localized keys (same for both languages).
pub fn key_count() -> usize {
    352
}
